/**
 * MZS Executive - Secure Backend Logic
 */

function doGet(e) {
  const action = e.parameter.action;
  const key = e.parameter.key;

  // New: Simple verification action for the frontend gatekeeper
  if (action === 'verify_key') {
    const masterKey = PropertiesService.getScriptProperties().getProperty('EXECUTIVE_KEY');
    return ContentService.createTextOutput(JSON.stringify({
      success: (key === masterKey)
    })).setMimeType(ContentService.MimeType.JSON);
  }

  // Default: Return survey data
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName('Responses') || ss.getSheets()[0];
  const data = sheet.getDataRange().getValues();
  return ContentService.createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const postData = JSON.parse(e.postData.contents);
  const action = postData.action;

  // New: Verify key on POST for extra security
  if (action === 'verify_key') {
    const masterKey = PropertiesService.getScriptProperties().getProperty('EXECUTIVE_KEY');
    return ContentService.createTextOutput(JSON.stringify({
      success: (postData.key === masterKey)
    })).setMimeType(ContentService.MimeType.JSON);
  }

  if (action === 'submit_response') {
    processResponse(postData.payload);
  } else if (action === 'sync_schema') {
    syncSchema(postData.questions);
  }
}

function processResponse(data) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Responses');
  if (!sheet) {
    sheet = ss.insertSheet('Responses');
  }

  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn() || 1).getValues()[0];
  const rowData = new Array(headers.length).fill('');

  rowData[0] = data.timestamp;
  rowData[1] = data.employeeEmail;
  rowData[2] = data.period;

  data.answers.forEach(ans => {
    const colIdx = headers.findIndex(h => h.toString().includes(`[ID:${ans.questionId}]`));
    if (colIdx > -1) rowData[colIdx] = ans.value;
  });

  sheet.appendRow(rowData);
}

function syncSchema(questions) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName('Responses');
  if (!sheet) {
    sheet = ss.insertSheet('Responses');
  }

  const existingHeaders = sheet.getLastColumn() > 0 ? sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0] : [];
  const fixedHeaders = ['Timestamp', 'Employee Email', 'Period'];
  const newHeaders = [...fixedHeaders];

  questions.forEach(q => {
    newHeaders.push(`${q.text} [ID:${q.id}]`);
  });

  sheet.getRange(1, 1, 1, newHeaders.length).setValues([newHeaders]);
  sheet.getRange(1, 1, 1, newHeaders.length).setFontWeight('bold').setBackground('#facc15');
}
```

