  // 2. Fetch Dashboard Data & Configuration
  const respSheet = ss.getSheetByName('Responses') || ss.insertSheet('Responses');
  const configSheet = ss.getSheetByName('AdminConfig') || ss.insertSheet('AdminConfig');

  const responses = (respSheet.getLastRow() > 0) ? respSheet.getDataRange().getValues() : [[]];
  const configJson = configSheet.getRange('C1').getValue();
  const questions = configJson ? JSON.parse(configJson) : [];

  return ContentService.createTextOutput(JSON.stringify({
    responses: responses,
    questions: questions
  })).setMimeType(ContentService.MimeType.JSON);
}

