```javascript
/**
 * MZS - Robust Backend v3.0
 */

function doGet(e) {
  const action = e.parameter.action;
  const key = e.parameter.key;
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // 1. Verify Access Key (for Dashboard)
  if (action === 'verify_key') {
    const configSheet = ss.getSheetByName('AdminConfig');
    let masterKey = "MZS123"; // Fallback
    if (configSheet) {
      const data = configSheet.getDataRange().getValues();
      for (let i = 0; i < data.length; i++) {
        if (data[i][0] === 'MasterKey') masterKey = data[i][1].toString();
      }
    }
    return ContentService.createTextOutput(JSON.stringify({ success: (key === masterKey) }))
      .setMimeType(ContentService.MimeType.JSON);
  }

  // 2. Fetch Data & Question Config (Combined for efficiency)
  const respSheet = ss.getSheetByName('Responses') || ss.insertSheet('Responses');
  const configSheet = ss.getSheetByName('AdminConfig') || ss.insertSheet('AdminConfig');

  const responses = (respSheet.getLastRow() > 0) ? respSheet.getDataRange().getValues() : [[]];
  const configJson = configSheet.getRange('C1').getValue();
  const questions = configJson ? JSON.parse(configJson) : [];

  return ContentService.createTextOutput(JSON.stringify({
    responses: responses,
    questions: questions
  })).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const postData = JSON.parse(e.postData.contents);

  // Action: Submit Survey Response
  if (postData.action === 'submit_response') {
    const data = postData.payload;
    let sheet = ss.getSheetByName('Responses') || ss.insertSheet('Responses');
    // Ensure we have at least 3 columns for metadata
    const lastCol = Math.max(sheet.getLastColumn(), 3);
    const headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
    const rowData = new Array(headers.length).fill('');

    rowData[0] = data.timestamp; 
    rowData[1] = data.employeeEmail; 
    rowData[2] = data.period;

    data.answers.forEach(ans => {
      // Find column index matching the unique Question ID
      const colIdx = headers.findIndex(h => h.toString().includes(`[ID:${ans.questionId}]`));
      if (colIdx > -1) rowData[colIdx] = ans.value;
    });
    sheet.appendRow(rowData);
  } 

  // Action: Sync Questions to Sheet Headers
  else if (postData.action === 'sync_schema') {
    let sheet = ss.getSheetByName('Responses') || ss.insertSheet('Responses');
    // Rebuild headers based on active questions
    const headers = ['Timestamp', 'Employee Email', 'Period', ...postData.questions.map(q => `${q.text} [ID:${q.id}]`)];
    sheet.getRange(1, 1, 1, headers.length).setValues([headers]);
    sheet.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#facc15');

    // Save the Question JSON to Cell C1 for the Survey to read
    let configSheet = ss.getSheetByName('AdminConfig') || ss.insertSheet('AdminConfig');
    configSheet.getRange('C1').setValue(JSON.stringify(postData.questions));
  }

  return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
}
